int lowest_factorial(int x) {
    int min_factorial = INT_MAX;
    for (int i = 1; i <= x; i++) {
        int factorial = 1;
        for (int j = 1; j <= i; j++) {
            factorial *= j;
        }
        if (factorial < min_factorial) {
            min_factorial = factorial;
        }
    }
    return min_factorial;
}

